const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const items = $input.all();

const requiredFields = [
  "Customer_ID",
  "Customer_Name",
  "Customer_Email",
  "Region",
  "Total_Spend",
  "Total_Orders",
  "Last_Purchase_Days",
  "Previous_Complaints"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const totalSpend = Number(data.Total_Spend);
  const totalOrders = Number(data.Total_Orders);
  const lastPurchaseDays = Number(data.Last_Purchase_Days);
  const previousComplaints = Number(data.Previous_Complaints);

  if (
    missingFields.length === 0 &&
    !isNaN(totalSpend) &&
    !isNaN(totalOrders) &&
    !isNaN(lastPurchaseDays) &&
    !isNaN(previousComplaints) &&
    totalSpend >= 0 &&
    totalOrders >= 0 &&
    lastPurchaseDays >= 0 &&
    previousComplaints >= 0
  ) {

    validItems.push({
      ...data,
      Total_Spend: totalSpend,
      Total_Orders: totalOrders,
      Last_Purchase_Days: lastPurchaseDays,
      Previous_Complaints: previousComplaints
    });

  } else {

    invalidItems.push({
      customer_id:
        data.Customer_ID || "Unknown",

      missing_fields:
        missingFields
    });
  }
}

return [
  {
    json: {
      data_valid:
        invalidItems.length === 0,

      total_customers:
        items.length,

      valid_customers:
        validItems.length,

      invalid_customers:
        invalidItems.length,

      invalid_details:
        invalidItems,

      customer_data:
        validItems
    }
  }
];

const customers = $json.customer_data;

const results = [];

for (const customer of customers) {

  const spend =
    Number(customer.Total_Spend);

  const orders =
    Number(customer.Total_Orders);

  const days =
    Number(customer.Last_Purchase_Days);

  const complaints =
    Number(customer.Previous_Complaints);

  let riskScore = 0;

  // Days since last purchase
  if (days > 90) {
    riskScore += 4;
  } else if (days > 60) {
    riskScore += 3;
  } else if (days > 30) {
    riskScore += 2;
  }

  // Previous complaints
  if (complaints >= 3) {
    riskScore += 3;
  } else if (complaints === 2) {
    riskScore += 2;
  } else if (complaints === 1) {
    riskScore += 1;
  }

  // Low order activity
  if (orders < 3) {
    riskScore += 2;
  }

  let retentionRisk;

  if (riskScore >= 7) {
    retentionRisk = "HIGH RISK";
  } else if (riskScore >= 4) {
    retentionRisk = "MEDIUM RISK";
  } else {
    retentionRisk = "LOW RISK";
  }

  results.push({
    ...customer,

    Risk_Score:
      riskScore,

    Retention_Risk:
      retentionRisk
  });
}

return [
  {
    json: {
      retention_customers:
        results
    }
  }
];

